<?php
namespace Srms;
final class Users {
 public static function create(array $d,bool $bootstrap=false): string {if(!$bootstrap)Auth::admin();$name=require_value($d,'full_name');$role=require_value($d,'role_id');$roleRow=Database::one('SELECT * FROM roles WHERE id=?',[$role])??throw new \DomainException('Role not found.');$hash=Auth::password(require_value($d,'password'));$phone=Auth::phone(require_value($d,'phone_number'));$ratepayer=trim($d['ratepayer_id']??'')?:null;if($roleRow['name']==='Property Owner'&&!$ratepayer)throw new \DomainException('Owner accounts require a linked ratepayer.');if($roleRow['name']!=='Property Owner'&&$ratepayer)throw new \DomainException('Only Property Owner users may link a ratepayer.');return Database::transaction(function()use($name,$role,$hash,$phone,$ratepayer,$bootstrap){Database::lock('roles',$role);if(Database::one('SELECT id FROM user_phone_numbers WHERE phone_number=?',[$phone]))throw new \DomainException('Phone is already used.');$rpPhone=Database::one('SELECT * FROM ratepayer_phone_numbers WHERE phone_number=?',[$phone]);if($rpPhone&&$rpPhone['ratepayer_id']!==$ratepayer)throw new \DomainException('Phone belongs to a different owner.');if($ratepayer&&Database::one('SELECT id FROM users WHERE ratepayer_id=?',[$ratepayer]))throw new \DomainException('This owner already has a user account.');$id=Database::insert('users',['full_name'=>$name,'role_id'=>$role,'ratepayer_id'=>$ratepayer,'password_hash'=>$hash,'must_change_password'=>1]);PhoneIdentity::claim($phone,$ratepayer?'ratepayer':'user',$ratepayer?:$id);if($ratepayer){if($rpPhone)Database::update('ratepayer_phone_numbers',$rpPhone['id'],['is_verified'=>1,'can_login'=>1]);else Database::insert('ratepayer_phone_numbers',['ratepayer_id'=>$ratepayer,'phone_number'=>$phone,'is_verified'=>1,'can_login'=>1,'is_primary'=>1]);}else Database::insert('user_phone_numbers',['user_id'=>$id,'phone_number'=>$phone,'is_verified'=>1,'can_login'=>1,'is_primary'=>1]);Audit::log($bootstrap?'administrator_bootstrap':'user_created','users',$id,null,['name'=>$name,'role_id'=>$role]);return $id;});}
 public static function update(array $d): void {Auth::admin();$id=require_value($d,'id');Database::transaction(function()use($id,$d){$u=Database::lock('users',$id);$v=[];if(isset($d['active'])&&$d['active']!==''){if(!in_array($d['active'],['0','1'],true))throw new \DomainException('Invalid access status.');if($id===Auth::user()['id']&&$d['active']==='0')throw new \DomainException('You cannot disable your own account.');$v['is_active']=$d['active']==='1'?1:0;}$password=(string)($d['password']??'');if($id===Auth::user()['id']&&$password!=='')throw new \DomainException('Use Change password to update your own password.');if($password!==''){$v['password_hash']=Auth::password($password);$v['must_change_password']=1;}if(!$v)throw new \DomainException('Choose an access change or enter a new password.');$v['session_version']=$u['session_version']+1;Database::update('users',$id,$v);Audit::log('user_updated','users',$id,null,['active'=>$v['is_active']??$u['is_active'],'password_reset'=>$password!=='']);});}
}

